ead><tr><th>Payment</th><th>Customer</th><th>Booking</th><th>Amount</th><th>Method</th><th>Receipt</th><th>Payment Status</th><th>Booking Status</th></tr></thead><tbody><?php while($r=mysqli_fetch_assoc($result)): ?><tr><td>#<?= (int)$r['payment_id'] ?></td><td><?= htmlspecialchars($r['name']) ?><br><small class="text-muted"><?= htmlspecialchars($r['email']) ?></small></td><td><?= htmlspecialchars($r['court_name']) ?><br><small><?= htmlspecialchars($r['booking_date']) ?> <?= htmlspecialchars(substr($r['booking_time'],0,5)) ?></small></td><td>RM <?= number_format((float)$r['amount'],2) ?></td><td><?= htmlspecialchars($r['payment_method'] ?? '-') ?></td><td><?php if($r['receipt']): ?><a target="_blank" href="../user/uploads/receipt/<?= rawurlencode($r['receipt']) ?>">View Receipt</a><?php else: ?>-<?php endif; ?></td><td><span class="badge <?= $r['status']==='Approved'?'bg-success':($r['status']==='Rejected'?'bg-danger':'bg-warning text-dark') ?>"><?= htmlspecialchars($r['status']) ?></span></td><td><span class="badge <?= $r['booking_status']==='Approved'?'bg-success':($r['booking_status']==='Rejected'?'bg-danger':'bg-warning text-dark') ?>"><?= htmlspecialchars($r['booking_status']) ?></span> <a href="manage_booking.php" class="small">manage &rarr;</a></td></tr><?php endwhile; ?></tbody></table></div></div></main></body></html>